"""Generierte HTML-Doku, Quellcode (opt-in), „Folie“ statt „Seite“."""

from pathlib import Path

import pytest

from localrag.config import load_config
from localrag.generation.prompts import source_label
from localrag.index.db import Database
from localrag.ingest.indexer import index_paths
from localrag.ingest.parsers import SkippedFile, parse
from localrag.retrieval.hybrid import search
from localrag.retrieval.keyword import SearchHit, page_label


@pytest.mark.parametrize(
    "head",
    [
        '<meta name="generator" content="Sphinx 7.2.6">',
        "<!-- Generated by javadoc (17) -->",
        "<div>Generated by Doxygen 1.9.8</div>",
    ],
)
def test_generated_documentation_is_skipped(tmp_path: Path, head: str):
    path = tmp_path / "api.html"
    path.write_text(f"<html><head>{head}</head><body><h1>os.path</h1><p>join()</p></body></html>")
    with pytest.raises(SkippedFile):
        parse(path)


def test_own_html_with_other_generator_is_kept(tmp_path: Path):
    path = tmp_path / "notiz.html"
    path.write_text('<meta name="generator" content="Microsoft Word 15"><p>Einkaufsliste</p>')
    assert parse(path)[0].text == "Einkaufsliste"


def test_code_is_split_at_top_level_definitions(tmp_path: Path):
    path = tmp_path / "tool.py"
    path.write_text(
        "import os\n\n\ndef lade_daten(pfad):\n    return open(pfad).read()\n\n\n"
        "class Rechner:\n    def summe(self, a, b):\n        return a + b\n",
        encoding="utf-8",
    )
    sections = parse(path)
    assert [s.heading_path for s in sections] == ["lade_daten", "Rechner"]  # kurze Importe hängen vorn dran
    assert "import os" in sections[0].text
    assert "def summe" in sections[1].text  # Methoden bleiben bei ihrer Klasse


def test_minified_code_is_skipped(tmp_path: Path):
    path = tmp_path / "bundle.min.js"
    path.write_text("var a=1;" * 10_000, encoding="utf-8")
    with pytest.raises(SkippedFile):
        parse(path)


def test_code_is_only_indexed_when_enabled(db: Database, tmp_path: Path):
    root = tmp_path / "docs"
    root.mkdir()
    (root / "skript.py").write_text("def stromkosten():\n    return 70\n", encoding="utf-8")
    (root / "notiz.md").write_text("Strom", encoding="utf-8")
    cfg_off = load_config(tmp_path / "fehlt.toml")
    assert index_paths(db, [root], extensions=cfg_off.extensions()).added == 1
    (tmp_path / "c.toml").write_text("code = true\n", encoding="utf-8")
    cfg_on = load_config(tmp_path / "c.toml")
    assert index_paths(db, [root], extensions=cfg_on.extensions()).added == 1  # jetzt auch skript.py
    assert search(db, "stromkosten", mode="keyword")[0].path.endswith("skript.py")


def hit(filetype: str, page: int) -> SearchHit:
    return SearchHit(1, 1, f"C:/x/vortrag.{filetype}", filetype, page, None, "t", 1.0, "t", ())


def test_slides_are_labelled_as_folie():
    assert page_label("pptx", 3) == "Folie 3"
    assert page_label("pdf", 3) == "Seite 3"
    assert source_label(hit("pptx", 2)) == "vortrag.pptx · Folie 2"
